drop policy if exists task_iterations_goal_owner_access on public.task_iterations; create policy task_iterations_goal_owner_select on public.task_iterations for select to authenticated using (exists(select 1 from public.tasks t join public.goals g on g.id=t.goal_id where t.id=task_id and g.owner_user_id=(select auth.uid()))); create policy task_iterations_goal_owner_insert on public.task_iterations for insert to authenticated with check (exists(select 1 from public.tasks t join public.goals g on g.id=t.goal_id where t.id=task_id and g.owner_user_id=(select auth.uid()))); drop policy if exists task_events_goal_owner_access on public.task_events; create policy task_events_goal_owner_select on public.task_events for select to authenticated using (exists(select 1 from public.tasks t join public.goals g on g.id=t.goal_id where t.id=task_id and g.owner_user_id=(select auth.uid()))); create policy task_events_goal_owner_insert on public.task_events for insert to authenticated with check (exists(select 1 from public.tasks t join public.goals g on g.id=t.goal_id where t.id=task_id and g.owner_user_id=(select auth.uid()))); drop policy if exists task_dependencies_goal_owner_access on public.task_dependencies; create policy task_dependencies_goal_owner_access on public.task_dependencies for all to authenticated using (exists(select 1 from public.tasks t join public.goals g on g.id=t.goal_id where t.id=task_id and g.owner_user_id=(select auth.uid()))) with check (exists(select 1 from public.tasks t join public.goals g on g.id=t.goal_id where t.id=task_id and g.owner_user_id=(select auth.uid()))); revoke update,delete on public.goal_versions,public.goal_events,public.task_iterations,public.task_events from authenticated; grant select,insert on public.goal_versions,public.goal_events,public.task_iterations,public.task_events to authenticated;